package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarUtils.parseOctal to maximize branch and line coverage.
 */
public class TarUtils_parseOctal_TriageGen0Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123 ".getBytes();
        // length 7, offset 0. end is 7. trailer is ' ' at index 6. end becomes 6.
        // next trailer is '3' at index 5. Wait, the logic for trailer is specific:
        // end-1 is ' ', so end becomes 6. Then end-1 is '3', which is not 0 or ' '.
        // Let's use a buffer that fits the logic: "  0123\0 "
        byte[] buf = "  0123\0 ".getBytes();
        // start=0, end=8. 
        // skip spaces: start becomes 2.
        // trailer = buf[7] (' ') -> end becomes 7.
        // trailer = buf[6] (0) -> end becomes 6.
        // loop from 2 to 6: '0','1','2','3'
        long result = TarUtils.parseOctal(buf, 0, buf.length);
        assertEquals(0123L, result);
    }

    @Test
    public void testParseOctal_AllNUL() {
        byte[] buffer = new byte[5]; // all 0
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 5));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooShort() {
        byte[] buffer = new byte[1];
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test
    public void testParseOctal_LeadingSpaces() {
        byte[] buffer = "   777\0".getBytes();
        // start=0, end=7.
        // skip spaces: start=3.
        // trailer = buf[6] (0) -> end=6.
        // trailer = buf[5] (7) -> end stays 6.
        // loop 3 to 6: '7','7','7'
        assertEquals(0777L, TarUtils.parseOctal(buffer, 0, 7));
    }

    @Test
    public void testParseOctal_TrailingSpaceAndNUL() {
        byte[] buffer = "123 \0 ".getBytes();
        // start=0, end=6.
        // trailer = buf[5] (' ') -> end=5.
        // trailer = buf[4] (0) -> end=4.
        // loop 0 to 4: '1','2','3',' ' -> wait, ' ' is not 0-7.
        // Correct buffer for logic: "123\0 "
        byte[] buf2 = "123\0 ".getBytes();
        // end=5. trailer=buf[4](' ') -> end=4. trailer=buf[3](0) -> end=3.
        // loop 0 to 3: '1','2','3'
        assertEquals(123L, TarUtils.parseOctal(buf2, 0, 5));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidTrailer() {
        byte[] buffer = "123A".getBytes();
        // end=4. trailer=buf[3]('A'). Not 0 or ' '.
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        byte[] buffer = "128\0 ".getBytes();
        // end=5. trailer=buf[4](' ') -> end=4. trailer=buf[3](0) -> end=3.
        // loop 0 to 3: '1','2','8'. '8' is invalid.
        TarUtils.parseOctal(buffer, 0, 5);
    }

    @Test
    public void testParseOctal_WithOffset() {
        byte[] buffer = "XXX 075\0".getBytes();
        // offset=3, length=5. end=8.
        // buffer[3..7] is " 075\0"
        // skip spaces: start=4.
        // trailer = buf[7](0) -> end=7.
        // trailer = buf[6](5) -> end=7.
        // loop 4 to 7: '0','7','5'
        assertEquals(075L, TarUtils.parseOctal(buffer, 3, 5));
    }

    @Test
    public void testParseOctal_MaxLong() {
        // Octal for a large number
        byte[] buffer = "777777777777\0 ".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, buffer.length);
        assertTrue(result > 0);
    }

    @Test
    public void testParseOctal_SingleTrailingSpace() {
        byte[] buffer = "0123 ".getBytes();
        // end=5. trailer=buf[4](' ') -> end=4.
        // trailer=buf[3]('3') -> end=4.
        // loop 0 to 4: '0','1','2','3'
        assertEquals(0123L, TarUtils.parseOctal(buffer, 0, 5));
    }

    @Test
    public void testParseOctal_SingleTrailingNUL() {
        byte[] buffer = "0123\0".getBytes();
        // end=5. trailer=buf[4](0) -> end=4.
        // trailer=buf[3]('3') -> end=4.
        // loop 0 to 4: '0','1','2','3'
        assertEquals(0123L, TarUtils.parseOctal(buffer, 0, 5));
    }
}
